sp_widget.client_script:
api.controller = function($scope, $timeout, $uibModal, spUtil, $window) {
    /* widget controller */
    const c = this;
    c.isSmall = false;
    c.loading = true;
    c.validDate = false;

    if (/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent)) {
        c.isMobile = true;
    } else {
        c.isMobile = false;
    }

    // Set initial values
    c.$onInit = function() {
        c.switchValue = 'delegated';
        if (!c.mobile) {
            sizeCheck();
        }
        setBaselineModalValues();
    };

    $scope.dateValidation = function() {
        c.validDate = new Date($scope.end_date.value) > new Date();
    };

    // Control auto-fill of modal fields
    c.setItem = function(obj) {
        if (obj) {
            c.delegateId = obj.sys_id;
            c.openModal('modify', obj);
        } else {
            c.openModal('create');
        }
    };

    // Modal handler
    c.openModal = function(type, obj) {
        c.type = type;

        if (obj) {
            $scope.delegate = {
                displayValue: obj.delegate_name.full,
                value: obj.delegate,
                name: 'delegate'
            };
			$scope.start_date = {
                displayValue: obj.starts,
                value: obj.starts,
                name: 'start_date'
            };
            $scope.end_date = {
                displayValue: obj.ends,
                value: obj.ends,
                name: 'end_date'
            };
            c.approvals = !!parseInt(obj.approvals);
            c.assignments = !!parseInt(obj.assignments);
            c.meeting = !!parseInt(obj.invitations);
            c.notifications = !!parseInt(obj.notifications);
        } else {
            setBaselineModalValues();
        }

        c.modalInstance = $uibModal.open({
            templateUrl: 'delegateAction',
            size: 'xs',
            scope: $scope
        });
    };

/////// start rbh ////
$scope.validateDates = function () {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const startVal = $scope.start_date.value;
    const endVal = $scope.end_date.value;

    // Si l'un des champs est vide → pas d'erreur pour l'instant
    if (!startVal && !endVal) {
        c.validDate = false;
        c.dateError = "";
        return;
    }

    const start = startVal ? new Date(startVal) : null;
    const end = endVal ? new Date(endVal) : null;

    // 1️⃣ Validation de la date de début
    if (start && start < today) {
        c.validDate = false;
        c.dateError = "La date de début ne peut pas être avant aujourd’hui.";
        $scope.start_date.value = ""; // Vide le champ
        return;
    }

    // 2️⃣ Validation de la date de fin
    if (end && end < today) {
        c.validDate = false;
        c.dateError = "La date de fin ne peut pas être avant aujourd’hui.";
        $scope.end_date.value = ""; // Vide le champ
        return;
    }

    if (start && end && end < start) {
        c.validDate = false;
        c.dateError = "La date de fin ne peut pas être avant la date de début.";
        $scope.end_date.value = ""; 
        return;
    }

    c.validDate = true;
    c.dateError = "";
};

$scope.$watchGroup(['start_date.value', 'end_date.value'], function () {
    $scope.validateDates();
});

////////// fin rbh //////
    // One action to rule CRUD
    c.uiAction = function(action, value) {
        c.data.action = action;

        c.loading = true;

        if (action == 'create' || action == 'modify') {
            c.modalInstance.close();
            delegateObj = {};
            if (action == 'modify') {
                delegateObj.sys_id = c.delegateId;
            }
            delegateObj.delegate = $scope.delegate.value;
            delegateObj.starts = $scope.start_date.value;
            delegateObj.ends = $scope.end_date.value;
            delegateObj.approvals = c.approvals;
            delegateObj.assignments = c.assignments;
            delegateObj.invitations = c.meeting;
            delegateObj.notifications = c.notifications;

            c.data.value = delegateObj;
        } else if (action == 'typeChange') {
            c.switchValue = value === 'delegates' ? 'delegated' : 'delegates';
            c.data.value = value;
        } else {
            c.data.value = value;
        }

        c.server.update().then(function(r) {
            c.data.action = undefined;
            c.data.value = undefined;
            c.delegateId = undefined;
            c.loading = false;
            setBaselineModalValues();
        });
    };


    // Watch for changes made outside of this widget
    const query = 'user=' + c.data.user;
    spUtil.recordWatch($scope, "sys_user_delegate", query, function(name, data) {
        c.uiAction('watcher');
    });

    const onresize = function(e) {
        sizeCheck();
    };
    $window.addEventListener("resize", onresize);

    // Dermine widget size for display purposes
    function sizeCheck() {
        $timeout(function() {
            var answer = false;
            var widget = document.getElementById(c.data.id);
            var widgetWidth = widget.clientWidth;
            if (widgetWidth < 768) {
                answer = true;
            }
            c.isSmall = answer;
            c.loading = false;

        });
    }

    // // Baselines modal values to empty
    // function setBaselineModalValues() {
    //     const modalValues = {
    //         displayValue: '',
    //         value: '',
    //     };

    //     $scope.delegate = {
    //        // modalValues,
    //         name: 'delegate'
    //     };
	// 	  $scope.start_date = {
    //        // modalValues,
    //         name: 'start_date'
    //     };
    //     $scope.end_date = {
    //        // modalValues,
    //         name: 'end_date'
    //     };
    //     c.approvals = false;
    //     c.assignments = false;
    //     c.meeting = false;
    //     c.notifications = false;
    // }

	function setBaselineModalValues() {
    $scope.delegate = {
        displayValue: '',
        value: '',
        name: 'delegate'
    };

    $scope.start_date = {
        displayValue: '',
        value: '',
        name: 'start_date'
    };

    $scope.end_date = {
        displayValue: '',
        value: '',
        name: 'end_date'
    };

    c.approvals = false;
    c.assignments = false;
    c.meeting = false;
    c.notifications = false;
}
};

sp_widget.css:
.type-change {
  font-size: .8em;
}

.panel-actions {
  float: right;
}

.no-delegates {
  text-align: center;
  align-items: center;
  padding: 0.5em 1em 0.5em 1em;
  border-top: 1px solid #ccc;
  color: #2e2e2e;
}

.add-color, .edit-color, .remove-color {
  color: #2e2e2e;
}

.mobile-delegate-wrapper {
  border-top: 1px solid #ccc;
}

.delegate {
  display: flex;
  align-items: center;
  padding: 0.5em 1em 0.5em 1em;
  border-top: 1px solid #ccc;
  color: #2e2e2e;
}

.mobile-options {
  display: flex;
  flex-grow: 3;
  text-align: right;
}

.mobile-left-action {
  flex-grow: 3;
  justify-content: right;
  margin-right: 2rem;
}

.mobile-delegate {
  display: flex;
  flex-direction: column;
  padding: 0.5em 1em 0.5em 1em;
  color: #2e2e2e;
}

.delegate > div:first-child {
  flex-basis: 15%; 
}

.delegate > div:last-child {
  flex-basis: 5%; 
}

.delegate-user {
  display: flex;
  flex: auto;
  align-items: center;
  min-width: 165px;
  text-overflow: ellipsis;
  overflow: hidden; 
}

.delegate-name {
  padding-left: 0.5em;
  margin-right: 0.5em;
}

.delegate-option {
  display: flex;
  flex-direction: row;
  align-items: center;
  flex: auto;
}

.option {
  padding: 2px 0px 2px 0px;
  margin: 2px;
  font-size: 1rem;
  width: 8em;
  text-align: center;
}

.enabled {
  opacity: 1 !important;
}

.disabled {
  background-color: #e3e3e4;
  opacity: 0.45;
}

.small-right-margin {
  margin-right: 1rem;
}

.delegate-dates {
  display: flex;
  flex-direction: column;
}

.date-container {
  display: inline;
  text-align: center;
}

.mobile-date-container {
  display: flex;
  flex-grow: 3;
}

.date-label {
  float: left;
}

.date {
  float: right;
  margin-left: 0.5em;
}

.actions-horizontal {
  display: flex;
  flex-direction: row;
  align-items: center;
  padding-right: 0.25em;
}

.actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding-right: 0.25em;
}

.crush-margin {
  margin-right: 0 px;
}

.medium-right-margin {
  margin-right: 2.5rem;
}

.action {
  cursor: pointer;
}

sp_widget.script:
(function() {

	// Initial settings
	var delegateUtils = new DelegateUtils();
	data.user = gs.getUserID();
	data.dateformat = gs.getSession().getUser().getDateFormat();
	var action = input.action;
	data.id = gs.generateGUID();
	var myDelegates = gs.getMessage("My Delegates");
	var myDelegated = gs.getMessage("Delegated to Me");

	var firstNameField = options.first_name_field || 'first_name';

	// Run defaults
	if (!input) {
		getAllDelegates();
		data.title = myDelegates;
		data.swapTitle = myDelegated;
	}

	// Adds a delegate record via a script include
	if (action == 'create' && input) {
		var create = delegateUtils.createDelegate(input.value);
		if (create) {
			gs.addInfoMessage(gs.getMessage('Delegate created successfully.'));
		} else {
			gs.addErrorMessage(gs.getMessage(('Delegate was not created.')));
		}
		getAllDelegates();
	}

	// Deletes a delegate record via script include
	if (action == 'remove' && input) {
		var del = delegateUtils.removeDelegate(input.value, options.delete_delegates);
		if (del) {
			gs.addInfoMessage(gs.getMessage('Delegate removed successfully.'));
		} else {
			gs.addErrorMessage(gs.getMessage('Delegate was not removed.'));
		}
		getAllDelegates();
	}

	// Modifies a delegate record via script include
	if (action == 'modify' && input) {
		var edit = delegateUtils.editDelegate(input.value);
		if (edit) {
			gs.addInfoMessage(gs.getMessage('Delegate modified successfully.'));
		} else {
			gs.addErrorMessage(gs.getMessage('Delegate was not modified.'));
		}
		getAllDelegates();
	}

	if (action == 'typeChange' && input) {
		if (input.value == 'delegated') {
			data.title = myDelegated;
			data.swapTitle = myDelegates;
		} else {
			data.title = myDelegates;
			data.swapTitle = myDelegated;
		}
		getAllDelegates(input.value);	
	} 

	if (action == 'watcher' && input) {
		getAllDelegates();
	}

	// Retrieves all delegates via script include
	function getAllDelegates(type) {
		var allDelegates = delegateUtils.getDelegates(data.user, data.dateformat, type, firstNameField);
		data.delegates = allDelegates.delegates;
	}

})();
